Theorem grow2 : PMSPA.opdel_spec RSEGS AD L ar HI -> forall (fx6 : FPState) R M model K LBX FF LK Aw cr ov fb b k stk d sp r pk pl kd ln B R6 M6 model6 Aw6,
    ri_inv HI (PEC.enc_own (PEC.ENC b k stk d) ++ LBX) FF LK cr Aw M (vml_of model) -> K [] -> PMSPA.entryA AD L ar R M sp r 0 ->
    PMSPA.aobjA FF ov 56 -> ov mod 8 = 0 -> PECA.enc_atA RSEGS EE L ar M ov fb (PEC.ENC b k stk d) -> Z.of_nat (length stk) = PEC.ecap k -> 0 < k <= 11 -> 0 <= pk < 2 ^ 47 -> 0 <= pl < 2 ^ 47 ->
    PEAEQGS.gmid L ar HI R M model LBX FF LK Aw cr ov b k stk sp pk pl kd ln B R6 M6 model6 Aw6 ->
    (forall (fx' : FPState) R' M' model' LK' Aw', regs_preserved R R' -> PECA.enc_atA RSEGS EE L ar M' ov fb (PEC.ENC B (k + 1) (stk ++ [EI kd ln 0]) d) ->
        PMSTA.base_okA RSEGS AD M' -> L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(ov + 24, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PEC.enc_own (PEC.ENC B (k + 1) (stk ++ [EI kd ln 0]) d) ++ LBX) FF LK' (adebit L cr (PEC.ESZ * PEC.ecap (k + 1))) Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
